var rows = JSON.parse(value);
if (!Array.isArray(rows)) { rows = []; }
var out = [];
for (var i = 0; i < rows.length; i++) {
  var r = {};
  for (var k in rows[i]) { r[k.toLowerCase()] = rows[i][k]; }
  var dns = String(r.ds_dnshostname || '').toLowerCase();
  if (!dns || dns === 'null') { continue; }
  var uac = parseInt(r.ds_useraccountcontrol, 10) || 0;
  if (uac & 2) { continue; }      // account disabled
  if (uac & 8192) { continue; }   // domain controller (SERVER_TRUST_ACCOUNT)
  var ip = String(r.ipaddress || '');
  if (!ip) { continue; }           // no A record in the DC DNS
  out.push({
    '{#AD.COMPUTER}': String(r.ds_cn || dns.split('.')[0]).toUpperCase(),
    '{#AD.DNSHOSTNAME}': dns,
    '{#AD.IP}': ip,
    '{#AD.DOMAIN}': dns.indexOf('.') > 0 ? dns.substr(dns.indexOf('.') + 1) : '',
    '{#AD.OS}': String(r.ds_operatingsystem || ''),
    '{#AD.MEMBER.DISCOVERY}': '1'
  });
}
return JSON.stringify(out);
